import React, { useState, useEffect } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from "./UserProfileCard";

export default function AdminDashboard({ reports, token, setMsg, admin }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);
  const [showAllFeedback, setShowAllFeedback] = useState(false);

  // New states for header stats (Option B: fetch from API)
  const [usersCount, setUsersCount] = useState("-");
  const [eventsCount, setEventsCount] = useState("-");
  const [volunteersCount, setVolunteersCount] = useState("-");

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };

  const loadData = async (endpoint, setter, expectedField = null, errMsg = "Failed to load") => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || errMsg);
        } catch {
          throw new Error(errMsg);
        }
      }

      const data = await res.json();

      if (expectedField && (data[expectedField] !== undefined && data[expectedField] !== null)) {
        setter(data[expectedField]);
        return;
      }

      const fallbackCandidates = [
        "top",
        "mostActive",
        "most",
        "badges",
        "ngos",
        "events",
        "volunteers",
        "donors",
        "results",
        "participants",
        "donations",
        "user_badges",
      ];

      for (const key of fallbackCandidates) {
        if (data[key] !== undefined && data[key] !== null) {
          setter(data[key]);
          return;
        }
      }

      if (Array.isArray(data)) {
        setter(data);
        return;
      }

      setter(data);
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    }
  };

  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to load most active NGO");
        } catch {
          throw new Error("Failed to load most active NGO");
        }
      }

      const data = await res.json();

      const candidate = data.mostActive || data.most || data.top || data.most_active || data[0] || null;

      if (Array.isArray(candidate)) {
        setMostActive(candidate[0] || null);
      } else {
        setMostActive(candidate || null);
      }
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to load most active NGO");
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to delete NGO");
        } catch {
          throw new Error("Failed to delete NGO");
        }
      }

      setMsg("NGO removed successfully");

      setNgos((prev) => (Array.isArray(prev) ? prev.filter((n) => n.id !== id) : prev));
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  const renderResults = (results) => {
    if (!results) return null;

    const list = Array.isArray(results) ? results : [results];

    if (!list.length) return <p>No data found.</p>;

    return list.map((item, i) => {
      if (item.title || item.event_title) {
        const title = item.title || item.event_title;
        const date = item.date || item.created_at || item.event_date;
        return (
          <div
            key={item.id || i}
            style={{
              padding: 8,
              background: "#fff",
              borderRadius: 8,
              marginBottom: 8,
            }}
          >
            <strong>{title}</strong>
            {date && <div style={{ fontSize: 13, color: "#666" }}>{date}</div>}
            {item.volunteers_count !== undefined && (
              <div style={{ fontSize: 13 }}>Volunteers: {item.volunteers_count}</div>
            )}
            {item.donations_sum !== undefined && (
              <div style={{ fontSize: 13 }}>Donations: ₹{item.donations_sum}</div>
            )}
          </div>
        );
      }

      if (item.name || item.user_name || item.donor_name || item.email) {
        const name = item.name || item.user_name || item.donor_name || item.email;
        return (
          <div
            key={item.id || i}
            style={{
              padding: 10,
              background: "#fff",
              borderRadius: 8,
              marginBottom: 8,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <strong>{name}</strong>
              {item.email && <div style={{ fontSize: 13, color: "#666" }}>{item.email}</div>}
              {item.amount !== undefined && <div style={{ fontSize: 13 }}>Amount: ₹{item.amount}</div>}
              {item.points !== undefined && <div style={{ fontSize: 13 }}>Points: {item.points}</div>}
            </div>

            <div style={{ fontSize: 12, color: "#666", textAlign: "right" }}>
              {item.created_at && <div>{new Date(item.created_at).toLocaleString()}</div>}
              {item.id && <div>ID: {item.id}</div>}
            </div>
          </div>
        );
      }

      if (item.title && item.description) {
        return (
          <div
            key={item.key || i}
            style={{
              padding: 10,
              background: "#fff",
              borderRadius: 8,
              marginBottom: 8,
            }}
          >
            <strong>{item.title}</strong>
            <div style={{ fontSize: 13, color: "#666" }}>{item.description || item.desc}</div>
            {item.key && <div style={{ fontSize: 12, color: "#666" }}>Key: {item.key}</div>}
          </div>
        );
      }

      return (
        <div
          key={i}
          style={{
            padding: 10,
            background: "#fff",
            borderRadius: 8,
            marginBottom: 8,
            wordBreak: "break-word",
          }}
        >
          <pre style={{ margin: 0, whiteSpace: "pre-wrap" }}>{JSON.stringify(item, null, 2)}</pre>
        </div>
      );
    });
  };

  // NEW: fetch counts from endpoints for header (Option B)
  const fetchStats = async () => {
    if (!token) {
      setUsersCount("-");
      setEventsCount("-");
      setVolunteersCount("-");
      return;
    }

    try {
      // Users
      try {
        const r1 = await fetch(`${API}/api/actions/users`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (r1.ok) {
          const d1 = await r1.json();
          // Try several fallbacks: array length, count field, total field
          const uCount = Array.isArray(d1) ? d1.length : d1.count ?? d1.total ?? d1.users?.length ?? "-";
          setUsersCount(typeof uCount === "number" ? uCount : (isNaN(Number(uCount)) ? uCount : Number(uCount)));
        } else {
          setUsersCount("-");
        }
      } catch (e) {
        console.error("users fetch error", e);
        setUsersCount("-");
      }

      // Events
      try {
        const r2 = await fetch(`${API}/api/actions/events`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (r2.ok) {
          const d2 = await r2.json();
          const eCount = Array.isArray(d2) ? d2.length : d2.count ?? d2.total ?? d2.events?.length ?? "-";
          setEventsCount(typeof eCount === "number" ? eCount : (isNaN(Number(eCount)) ? eCount : Number(eCount)));
        } else {
          setEventsCount("-");
        }
      } catch (e) {
        console.error("events fetch error", e);
        setEventsCount("-");
      }

      // Volunteers
      try {
        const r3 = await fetch(`${API}/api/actions/volunteers`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (r3.ok) {
          const d3 = await r3.json();
          const vCount = Array.isArray(d3) ? d3.length : d3.count ?? d3.total ?? d3.volunteers?.length ?? "-";
          setVolunteersCount(typeof vCount === "number" ? vCount : (isNaN(Number(vCount)) ? vCount : Number(vCount)));
        } else {
          setVolunteersCount("-");
        }
      } catch (e) {
        console.error("volunteers fetch error", e);
        setVolunteersCount("-");
      }
    } catch (err) {
      console.error(err);
      setMsg("Failed to load header stats");
    }
  };

  // Fetch header stats when token becomes available
  useEffect(() => {
    fetchStats();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  return (
    <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
      <div style={{ flex: 1 }}>
        {/* HEADER CARD - redesigned to match screenshot */}
        <div
          style={{
            background: "linear-gradient(180deg, rgba(255,255,255,0.98), rgba(255,255,255,0.98))",
            padding: 20,
            borderRadius: 12,
            marginBottom: 20,
            boxShadow: "0 6px 30px rgba(2,6,23,0.06)",
            display: "flex",
            alignItems: "center",
            gap: 20,
            flexWrap: "wrap",
          }}
        >
          {/* Left: Avatar & admin text */}
          <div style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 240 }}>
            <div
              style={{
                width: 64,
                height: 64,
                borderRadius: 12,
                background: "#fff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: "0 6px 20px rgba(2,6,23,0.05)",
                fontSize: 28,
              }}
            >
              👤
            </div>

            <div>
              <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 6 }}>
                Administrator
              </div>
              <div style={{ fontSize: 13, color: "#6b7280", marginBottom: 6 }}>
                {admin?.email || "admin@ngo.local"}
              </div>
              <div
                style={{
                  display: "inline-block",
                  padding: "4px 8px",
                  borderRadius: 999,
                  background: "#fff0f6",
                  color: "#c41d7f",
                  fontSize: 12,
                  fontWeight: 600,
                }}
              >
                Admin
              </div>
            </div>
          </div>

          {/* Spacer */}
          <div style={{ flex: 1 }} />

          {/* Stats boxes */}
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <div
              style={{
                minWidth: 120,
                background: "#f3f4f6",
                padding: "14px 18px",
                borderRadius: 10,
                textAlign: "center",
                boxShadow: "inset 0 -1px 0 rgba(0,0,0,0.02)",
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 700 }}>{usersCount ?? "-"}</div>
              <div style={{ fontSize: 12, color: "#6b7280" }}>Users</div>
            </div>

            <div
              style={{
                minWidth: 120,
                background: "#f3f4f6",
                padding: "14px 18px",
                borderRadius: 10,
                textAlign: "center",
                boxShadow: "inset 0 -1px 0 rgba(0,0,0,0.02)",
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 700 }}>{eventsCount ?? "-"}</div>
              <div style={{ fontSize: 12, color: "#6b7280" }}>Events</div>
            </div>

            <div
              style={{
                minWidth: 120,
                background: "#f3f4f6",
                padding: "14px 18px",
                borderRadius: 10,
                textAlign: "center",
                boxShadow: "inset 0 -1px 0 rgba(0,0,0,0.02)",
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 700 }}>{volunteersCount ?? "-"}</div>
              <div style={{ fontSize: 12, color: "#6b7280" }}>Volunteers</div>
            </div>
          </div>
        </div>

        <AchievementsPanel
          token={token}
          me={{ points: reports?.adminPoints || 0 }}
          role="user"
          setMsg={setMsg}
        />

        <h3 style={{ marginTop: 6 }}>Admin Reports</h3>

        <div className="cards" style={{ display: "flex", gap: 12, marginTop: 12 }}>
          <div
            className="stat-card"
            style={{
              flex: 1,
              background: "#fff",
              padding: 16,
              borderRadius: 10,
              boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
            }}
          >
            <div className="stat-num" style={{ fontSize: 20, fontWeight: 700 }}>
              {reports?.donations
                ? reports.donations.reduce(
                    (sum, d) => sum + parseFloat(d.amount || 0),
                    0
                  )
                : "-"}
            </div>
            <div className="stat-label" style={{ fontSize: 12, color: "#6b7280" }}>
              Total Donation Amount (₹)
            </div>
          </div>

          <div
            className="stat-card"
            style={{
              flex: 1,
              background: "#fff",
              padding: 16,
              borderRadius: 10,
              boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
            }}
          >
            <div className="stat-num" style={{ fontSize: 20, fontWeight: 700 }}>
              {reports?.volunteers?.length || 0}
            </div>
            <div className="stat-label" style={{ fontSize: 12, color: "#6b7280" }}>
              Total Volunteers
            </div>
          </div>

          <div
            className="stat-card"
            style={{
              flex: 1,
              background: "#fff",
              padding: 16,
              borderRadius: 10,
              boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
            }}
          >
            <div className="stat-num" style={{ fontSize: 20, fontWeight: 700 }}>
              {reports?.feedbacks?.length || 0}
            </div>
            <div className="stat-label" style={{ fontSize: 12, color: "#6b7280" }}>
              Feedbacks
            </div>
          </div>
        </div>

        <div style={{ marginTop: 12 }}>
          <button
            onClick={() =>
              loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
            }
            style={{
              padding: "8px 12px",
              borderRadius: 8,
              border: "none",
              background: "#0ea5a2",
              color: "white",
              cursor: "pointer",
              marginRight: 8,
            }}
          >
            View Registered NGOs
          </button>

          <button
            style={{ marginLeft: 8, padding: "8px 12px", borderRadius: 8, cursor: "pointer" }}
            onClick={() =>
              loadData(
                "/api/actions/registered-events",
                setEvents,
                "events",
                "Failed to load events"
              )
            }
          >
            View Registered Events
          </button>

          <button
            style={{
              marginLeft: 8,
              padding: "8px 12px",
              borderRadius: 8,
              cursor: "pointer",
            }}
            onClick={() =>
              loadData(
                "/api/actions/event-stats",
                setEventStats,
                "events",
                "Failed to load event stats"
              )
            }
          >
            View Event Stats
          </button>
        </div>

        {events && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered Events</h4>
            {Array.isArray(events) && events.length ? (
              events.map((e) => (
                <div
                  key={e.id}
                  style={{
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                  }}
                >
                  <strong>{e.title}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{e.date || e.created_at}</div>
                </div>
              ))
            ) : (
              <p>No events registered.</p>
            )}
          </div>
        )}

        {eventStats && eventStats.mode !== "donors" && eventStats.mode !== "volunteers" && (
          <div style={{ marginTop: 20 }}>
            <h4>Results</h4>
            {renderResults(eventStats)}
          </div>
        )}

        {/* If eventStats set by Top Volunteers/Donors buttons (see right panel) */}
        {eventStats && (eventStats.mode === "donors" || eventStats.mode === "volunteers") && (
          <div style={{ marginTop: 20 }}>
            <h4>
              {eventStats.mode === "volunteers"
                ? "Top Volunteers"
                : eventStats.mode === "donors"
                ? "Top Donors"
                : "Results"}
            </h4>

            <table style={{ width: "100%", background: "white", borderRadius: 8 }}>
              <thead>
                <tr style={{ background: "#fafafa" }}>
                  <th style={{ padding: 8, textAlign: "left" }}>#</th>
                  <th style={{ padding: 8, textAlign: "left" }}>Name / Email</th>

                  {eventStats.mode === "volunteers" && <th style={{ padding: 8 }}>Points</th>}
                  {eventStats.mode === "donors" && <th style={{ padding: 8 }}>Amount (₹)</th>}
                </tr>
              </thead>

              <tbody>
                {Array.isArray(eventStats.list) && eventStats.list.length ? (
                  eventStats.list.map((item, index) => (
                    <tr
                      key={index}
                      style={{
                        background: index === 0 ? "#fff1b8" : "white",
                        fontWeight: index === 0 ? 600 : 400,
                      }}
                    >
                      <td style={{ padding: 8 }}>{index + 1}</td>
                      <td style={{ padding: 8 }}>{item.name || item.email || "—"}</td>

                      {eventStats.mode === "volunteers" && (
                        <td style={{ padding: 8 }}>{item.points || 0}</td>
                      )}

                      {eventStats.mode === "donors" && (
                        <td style={{ padding: 8 }}>₹{item.amount || 0}</td>
                      )}
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={3} style={{ padding: 12 }}>
                      No data available.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        {ngos && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered NGOs</h4>
            {Array.isArray(ngos) && ngos.length ? (
              ngos.map((n) => (
                <div
                  key={n.id}
                  style={{
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div>
                    <strong>{n.name}</strong>
                    <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                  </div>

                  <button
                    style={{
                      padding: "6px 12px",
                      background: "red",
                      color: "white",
                      border: "none",
                      borderRadius: 6,
                      cursor: "pointer",
                    }}
                    onClick={() => deleteNgo(n.id)}
                  >
                    Remove
                  </button>
                </div>
              ))
            ) : (
              <p>No NGOs registered.</p>
            )}
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div
        style={{
          width: 320,
          flexShrink: 0,
          position: "sticky",
          top: 16,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        {/* Quick Actions */}
        <div
          style={{
            background: "#fffbe6",
            padding: 12,
            borderRadius: 10,
            border: "2px solid #ffe58f",
            boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
          }}
        >
          <h4>Quick Actions</h4>

          {/* TOP VOLUNTEERS - fetch all and show table */}
          <button
            onClick={async () => {
              if (!token) return setMsg("Login as admin first");
              clearAll();
              try {
                const res = await fetch(`${API}/api/actions/top-volunteers`, {
                  headers: { Authorization: `Bearer ${token}` },
                });
                if (!res.ok) {
                  let txt = await res.text();
                  try {
                    const j = JSON.parse(txt);
                    throw new Error(j.message || "Failed to load top volunteers");
                  } catch {
                    throw new Error("Failed to load top volunteers");
                  }
                }
                const data = await res.json();
                let list = Array.isArray(data.top) ? data.top : Array.isArray(data) ? data : data.results ?? data.list ?? data.items ?? [];
                // Ensure it's an array
                if (!Array.isArray(list)) {
                  // try to find arrays in object
                  const possibleArrays = Object.keys(data).map(k => data[k]).filter(v => Array.isArray(v));
                  list = possibleArrays[0] || [];
                }
                // sort descending by points if present
                list.sort((a, b) => (b.points || 0) - (a.points || 0));
                setEventStats({ mode: "volunteers", list });
              } catch (err) {
                console.error(err);
                setMsg(err.message || "Failed to load top volunteers");
              }
            }}
            style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
          >
            Top Volunteers
          </button>

          {/* TOP DONORS - fetch all and show table */}
          <button
            onClick={async () => {
              if (!token) return setMsg("Login as admin first");
              clearAll();
              try {
                const res = await fetch(`${API}/api/actions/top-donors`, {
                  headers: { Authorization: `Bearer ${token}` },
                });
                if (!res.ok) {
                  let txt = await res.text();
                  try {
                    const j = JSON.parse(txt);
                    throw new Error(j.message || "Failed to load top donors");
                  } catch {
                    throw new Error("Failed to load top donors");
                  }
                }
                const data = await res.json();
                let list = Array.isArray(data.top) ? data.top : Array.isArray(data) ? data : data.results ?? data.list ?? data.items ?? [];
                if (!Array.isArray(list)) {
                  const possibleArrays = Object.keys(data).map(k => data[k]).filter(v => Array.isArray(v));
                  list = possibleArrays[0] || [];
                }
                list.sort((a, b) => (b.amount || 0) - (a.amount || 0));
                setEventStats({ mode: "donors", list });
              } catch (err) {
                console.error(err);
                setMsg(err.message || "Failed to load top donors");
              }
            }}
            style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
          >
            Top Donors
          </button>

          <button
            onClick={() =>
              loadData("/api/actions/badges", setEventStats, "badges", "Failed to load badges")
            }
            style={{ width: "100%", padding: 10, borderRadius: 8 }}
          >
            View Badges
          </button>
        </div>

        {/* Most Active NGO */}
        <div
          style={{
            background: "#e6f7ff",
            padding: 12,
            borderRadius: 10,
            border: "2px solid #91d5ff",
            boxShadow: "0 6px 20px rgba(8, 8, 9, 0.04)",
          }}
        >
          <h4>Most Active NGO</h4>

          <button
            onClick={loadMostActive}
            style={{ marginTop: 8, padding: 8, width: "100%", borderRadius: 6 }}
          >
            Load Most Active NGO
          </button>

          {mostActive && (
            <div style={{ marginTop: 12 }}>
              <strong>{mostActive.name}</strong>
              <div style={{ fontSize: 13, color: "#666" }}>
                Activity Score: {(mostActive?.activity_score ?? mostActive?.activityScore ?? mostActive?.activity) ?? "N/A"}
              </div>
            </div>
          )}
        </div>

        {/* NEW FEEDBACK BOX WITH VIEW MORE */}
        <div
          style={{
            background: "#fffde7",
            padding: 12,
            borderRadius: 10,
            border: "2px solid #ffc107",
            boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
            maxHeight: 250,
            overflowY: "auto",
          }}
        >
          <h4>User Feedback</h4>

          {(() => {
            const fb = reports?.feedbacks || [];
            if (!fb.length) return <p>No feedback available.</p>;

            // sort by newest first just in case
            const sorted = [...fb].sort(
              (a, b) => new Date(b.created_at) - new Date(a.created_at)
            );

            const visibleFeedbacks = showAllFeedback ? sorted : [sorted[0]];

            return (
              <>
                {visibleFeedbacks.map((f, i) => (
                  <div
                    key={i}
                    style={{
                      background: "#f8f8f8ff",
                      padding: 8,
                      borderRadius: 8,
                      marginBottom: 8,
                    }}
                  >
                    <strong>{f.email || f.name || "User"}</strong>
                    <div style={{ fontSize: 13, color: "#666" }}>
                      {new Date(f.created_at).toLocaleString()}
                    </div>
                    <div style={{ marginTop: 4 }}>{f.text}</div>
                  </div>
                ))}

                <button
                  onClick={() => setShowAllFeedback((prev) => !prev)}
                  style={{
                    width: "100%",
                    padding: "8px",
                    borderRadius: 6,
                    background: "#ff8f00",
                    color: "white",
                    border: "none",
                    cursor: "pointer",
                    marginTop: 4,
                  }}
                >
                  {showAllFeedback ? "View Less" : "View More"}
                </button>
              </>
            );
          })()}
        </div>
      </div>
    </div>
  );
}
